import * as AirbusIcons from "@airbus/icons";

export const copyToClipboard = (value: string) => {
  navigator.clipboard.writeText(value);
  window.alert("Copied to clipboard: \"" + value + "\"");
};

export const getAirbusIcons = () => {
  return Object.keys(AirbusIcons);
};

export const getIconID = (iconKey: string) => {
  const name: string = (AirbusIcons as any)[iconKey].name;
  const id = name.replace(/([A-Z])/g, (_, p1) => {
    return "_" + p1.toLowerCase();
  });
  return id;
};
